{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"Maximum tenant screening fee for 2026","requirement":"A landlord may not charge more than $68.96 as a tenant screening fee in 2026, must accept a reusable screening report the applicant provides, and must give a receipt, a copy of any credit report obtained, and a refund of unused amounts.","key_value":"$68.96 for 2026","coverage_conditions":"Prospective tenants applying to rent residential property in California; the page states the statewide maximum screening fee for 2026.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":"Berkeley Mun. Code § 13.78.010 requires owners to disclose this state maximum fee cap to applicants.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee disclosure and non-refundable application fee rules","requirement":"An owner or agent who charges a screening fee must give applicants a tenant screening fee rights statement and the state fee-cap statement before taking the fee, and may not charge an existing tenant a non-refundable fee to renew a tenancy or change a roommate.","key_value":null,"coverage_conditions":"All residential rental agreements in Berkeley, whatever the lease says; applies to owners and agents who charge screening fees and to fees charged to existing tenants.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All residential rental agreements in Berkeley"},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the chapter is unenforceable.","effective_date":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":"The required disclosure must state the maximum fee cap permitted under California Civil Code Section 1950.6(b).","confidence":0.9,"conflict_flag":false,"conflict_note":null}
